<?php
require __DIR__.'/../includes/bootstrap.php';admin_required();
$rows=$pdo->query("SELECT l.*,u.full_name,u.username,u.role,m.full_name AS member_name FROM activity_logs l LEFT JOIN users u ON u.id=l.user_id LEFT JOIN members m ON m.id=l.member_id WHERE l.action IN('staff_login','login_failed','member_login') ORDER BY l.created_at DESC LIMIT 100")->fetchAll();
$page_title='Login Monitor';require __DIR__.'/../includes/header.php';?>
<div><?php require __DIR__.'/../includes/admin_sidebar.php';?><main class="main"><header class="topbar"><div class="d-flex align-items-center gap-3"><button class="menu-btn" data-sidebar-toggle><i class="bi bi-list"></i></button><div><h1>Login Monitor</h1><p>Audit recent authentication activity across the church platform.</p></div></div></header><div class="content"><div class="cardx p-4"><div class="table-responsive"><table class="table table-clean align-middle"><thead><tr><th>Person</th><th>Role</th><th>Action</th><th>IP</th><th>Device</th><th>Time</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['full_name']??$r['member_name']??'Unknown')?><br><small class="text-muted"><?=e($r['username']??'Member')?></small></td><td><?=e($r['role']??'member')?></td><td><?=e($r['action'])?></td><td><?=e($r['ip_address'])?></td><td><small><?=e($r['user_agent'])?></small></td><td><?=e(date('d M Y, g:i A',strtotime($r['created_at'])))?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="empty">No authentication activity yet.</td></tr><?php endif;?></tbody></table></div></div></div></main></div>
